<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit(1);}require __DIR__.'/_bootstrap.php';
use Ishep\Repositories\AuditLogRepository;use Ishep\Services\UserAdministrationService;
$args=$argv;array_shift($args);$command=array_shift($args)??'help';$options=[];foreach($args as $arg){if(str_starts_with($arg,'--')&&str_contains($arg,'=')){[$key,$value]=explode('=',substr($arg,2),2);$options[$key]=$value;}elseif(str_starts_with($arg,'--'))$options[substr($arg,2)]=true;}
$required=static function(string $key)use($options):string{$value=trim((string)($options[$key]??''));if($value==='')throw new DomainException('Missing --'.$key.'.');return$value;};
try{$service=new UserAdministrationService(cli_db(),new AuditLogRepository(cli_db()));if($command==='create'){$password='';if(isset($options['password-stdin']))$password=rtrim((string)stream_get_contents(STDIN),"\r\n");elseif(PHP_OS_FAMILY!=='Windows'&&function_exists('shell_exec')){$password=rtrim((string)shell_exec('stty -echo; printf "Password: " > /dev/tty; head -n 1 /dev/tty; stty echo; printf "\\n" > /dev/tty'),"\r\n");}else throw new DomainException('Pipe a temporary password through standard input with --password-stdin.');$id=$service->create($required('name'),$required('email'),$password,(int)$required('membership-type'));fwrite(STDOUT,"Created user ID {$id} with registered_user role.\n");}
elseif($command==='assign-role'){$service->assign($required('email'),$required('role'));fwrite(STDOUT,"Role assigned.\n");}
elseif($command==='remove-role'){if(!isset($options['confirm']))throw new DomainException('Role removal requires --confirm.');$service->remove($required('email'),$required('role'));fwrite(STDOUT,"Role removed.\n");}
elseif($command==='list-roles'){fwrite(STDOUT,implode(PHP_EOL,$service->roles($required('email'))).PHP_EOL);}
elseif($command==='set-status'){if($required('status')==='suspended'&&!isset($options['confirm']))throw new DomainException('Suspension requires --confirm.');$service->status($required('email'),$required('status'));fwrite(STDOUT,"Account status updated.\n");}
else{fwrite(STDOUT,"Usage: php plain-php/bin/user-admin.php create --name=NAME --email=EMAIL --membership-type=ID --password-stdin\n  assign-role --email=EMAIL --role=ROLE\n  remove-role --email=EMAIL --role=ROLE --confirm\n  list-roles --email=EMAIL\n  set-status --email=EMAIL --status=active|suspended [--confirm]\n");exit($command==='help'?0:2);}}catch(Throwable $e){fwrite(STDERR,'ERROR: '.$e->getMessage().PHP_EOL);exit(1);}
